"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4961],{9809:n=>{n.exports=JSON.parse('{"functions":[{"name":"array","desc":"Ordered list.\\n\\n**Syntax:** `array<T> name = { a, b, c };`\\n\\n**Emit:** `{T}`\\n\\n```clpp\\narray<string> names = {\\"Kartz\\", \\"Player1\\"};\\nfor (string n : names) {\\n    post(n);\\n}\\n```\\n\\nIterate with range-for. `Vector3` is a datatype, not `vector<T>`.","params":[],"returns":[],"function_type":"static","source":{"line":28,"path":"moonwave/Collections.lua"}},{"name":"vector","desc":"Alias of `array<T>`. Not `Vector3`.\\n\\n**Syntax:** `vector<T> name = { a, b };`\\n\\n**Emit:** `{T}`","params":[],"returns":[],"function_type":"static","source":{"line":39,"path":"moonwave/Collections.lua"}},{"name":"dictionary","desc":"String-keyed (or typed-key) map. Access keys with `:`, not `.`.\\n\\n**Syntax:**\\n```clpp\\ndictionary<string, int> stats = {\\n    {\\"Coins\\", 100},\\n    {\\"Gems\\", 50}\\n};\\npost(stats:Coins);\\n```\\n\\n**Emit:** `{ [K]: V }` with `Key = value` fields","params":[],"returns":[],"function_type":"static","source":{"line":57,"path":"moonwave/Collections.lua"}}],"properties":[],"types":[],"name":"Collections","desc":"Arrays are ordered lists. Dictionaries are maps. Both become Luau tables.\\n\\nAliases: `vector<T>`, `LuaArray<T>`, `span<T>` \u2192 `{T}`. `map<K,V>` \u2192 `{ [K]: V }`.","source":{"line":9,"path":"moonwave/Collections.lua"}}')}}]);